//! 🧪️ Original group digest transport preserves native edit custody, exact grants and independent fixture digests.
use semio_framework_os_kernel::{os_store::{admit_artifact_batch_digest,artifact_batch_digest_birth_demand},os_spr::Edit};
use semio_framework_value::{RetirementDemand,retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::controlled::ControlledRetirement};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn below(full:RetainedCloneGrant)->[RetainedCloneGrant;5]{[RetainedCloneGrant{maximum_items:0,..full},RetainedCloneGrant{maximum_copy_bytes:full.maximum_copy_bytes.saturating_sub(1),..full},RetainedCloneGrant{maximum_capacity_bytes:full.maximum_capacity_bytes.saturating_sub(1),..full},RetainedCloneGrant{maximum_release_bytes:full.maximum_release_bytes.saturating_sub(1),..full},RetainedCloneGrant{maximum_depth:full.maximum_depth.saturating_sub(1),..full}]}
#[test]
fn original_group_digest_wrapper_retains_native_edit_and_separate_physical_frame(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🔣️.json")).unwrap();let maximum_turns=policy["maximumTurns"].as_u64().unwrap()as usize;
 let cases:serde_json::Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../../🔨️modules/📡️replication/🎮️mutation/🧵️canonical/🧫️fixtures/🔣️.json"))).unwrap();
 let expected:serde_json::Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../../🔨️modules/📡️replication/🎮️mutation/🧵️canonical/🔏️seal/🧫️fixtures/🔣️.json"))).unwrap();
 for(index,row)in cases["cases"].as_array().unwrap().iter().enumerate(){for pause in policy["law"]["nativeDigestCancellationTurns"].as_array().unwrap(){let cancel_at=pause.as_u64().map(|turn|turn as usize);
  let encoded=serde_json::to_string(&row["edit"]).unwrap();let(original,heap)=observe(||Box::new(semio_framework_pack_json::from_json_str::<Edit<bool>>(&encoded,semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()));let held=heap.requested_bytes-heap.released_bytes;let mut born=0;let mut released=0;let mut original=Some(original);let pointer=std::ptr::from_ref(original.as_ref().unwrap().as_ref());let id=original.as_ref().unwrap().id.as_ptr();let forwards=original.as_ref().unwrap().forwards.as_ptr();
  let full=grant(artifact_batch_digest_birth_demand::<bool>().unwrap());
  for denied in below(full){if denied==full{continue;}let(result,heap)=observe(||admit_artifact_batch_digest(&mut original,denied).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(std::ptr::from_ref(original.as_ref().unwrap().as_ref()),pointer);assert_eq!(original.as_ref().unwrap().id.as_ptr(),id);}
  let(result,heap)=observe(||admit_artifact_batch_digest(&mut original,full).unwrap());let(mut owner,receipt)=result.unwrap();born+=heap.requested_bytes;released+=heap.released_bytes;assert!(original.is_none());assert!(receipt.fits(full));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));let mut turns=0;let mut cancelled=false;
  while !owner.terminal_is_empty(){assert!(turns<maximum_turns);if cancel_at==Some(turns){owner.begin_close();cancelled=true;}
   let full=grant(owner.next_digest_demand().unwrap());
   for denied in below(full){if denied==full{continue;}let before=owner.next_digest_demand().unwrap();let(step,heap)=observe(||if owner.ready(){assert!(owner.take_edit(denied).unwrap().is_none());semio_framework_value::RetainedCloneStep::Progress(Default::default())}else{owner.advance_digest(denied).unwrap()});assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(owner.next_digest_demand().unwrap(),before);}
   if owner.ready(){assert!(!cancelled);let(result,heap)=observe(||owner.take_edit(full).unwrap());let(edit,digest,receipt)=result.unwrap();born+=heap.requested_bytes;released+=heap.released_bytes;assert!(receipt.fits(full));assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(std::ptr::from_ref(edit.as_ref()),pointer);assert_eq!(edit.id.as_ptr(),id);assert_eq!(edit.forwards.as_ptr(),forwards);let hex:String=digest.iter().map(|byte|format!("{byte:02x}")).collect();assert_eq!(hex,expected["rows"][index]["digest"].as_str().unwrap());let mut retirement=ControlledRetirement::new(edit).unwrap_or_else(|(error,_)|panic!("original edit closure: {error}"));for _ in 0..maximum_turns{if retirement.terminal_is_empty(){break;}let work=retirement.next_copy_byte_demand().unwrap();let full=grant(RetirementDemand{copy_bytes:work,capacity_bytes:retirement.next_capacity_byte_demand(work).unwrap(),release_bytes:retirement.next_release_byte_demand().unwrap(),depth:retirement.next_depth_demand().unwrap()});let(step,heap)=observe(||retirement.step(full).unwrap());born+=heap.requested_bytes;released+=heap.released_bytes;assert!(step.progress().fits(full));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(retirement.terminal_is_empty());let((),heap)=observe(||drop(retirement));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));break;}
   let(step,heap)=observe(||owner.advance_digest(full).unwrap());born+=heap.requested_bytes;released+=heap.released_bytes;assert!(step.progress().fits(full));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));turns+=1;
  }
  assert!(owner.terminal_is_empty());let frame=std::mem::size_of_val(owner.as_ref());let mut owner=Some(owner);let full=RetainedCloneGrant{maximum_items:1,maximum_release_bytes:frame,maximum_depth:1,..Default::default()};for denied in below(full){if denied==full{continue;}let(result,heap)=observe(||{if denied.maximum_items==0||denied.maximum_release_bytes<frame||denied.maximum_depth==0{false}else{drop(owner.take());true}});assert!(!result);assert!(owner.is_some());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let((),heap)=observe(||drop(owner.take()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,frame));released+=heap.released_bytes;assert_eq!(released,held+born);let((),heap)=observe(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  eprintln!("[DEBUG] original group digest wrapper case={index} cancellation={cancel_at:?} cancelled={cancelled} turns={turns}; native original Box/id/forward custody, independent NodeSHA256, five grants, separate outerFrame={frame}, held={held} born={born} released={released}, terminalDrop0");
 }}
}
